      '.mpg': 'video/mpeg',
      '.mpeg': 'video/mpeg',
      '.wmv': 'video/wmv',
      '.flv': 'video/x-flv',
      '.3gp': 'video/3gpp',
    };

    test('every routed extension carries its real container MIME', () async {
      for (final entry in expectedMimes.entries) {
        final path = '/work/clip${entry.key}';
